#pragma once
#include "tilemap_data.h"
#include "timeline_model.h"
#include <cmath>
#include <set>
#include <winrt/Windows.Data.Json.h>
#include <winrt/Windows.Foundation.Collections.h>
namespace moon::project::tilejson {
using namespace winrt::Windows::Data::Json;
inline int integer(const JsonObject& o,const wchar_t* k,int lo,int hi){if(!o.HasKey(k)||o.GetNamedValue(k).ValueType()!=JsonValueType::Number)throw std::invalid_argument("Missing tile integer");const double n=o.GetNamedNumber(k);if(!std::isfinite(n)||std::floor(n)!=n||n<lo||n>hi)throw std::invalid_argument("Invalid tile integer");return int(n);}
inline std::string string(const JsonObject& o,const wchar_t* k){if(!o.HasKey(k)||o.GetNamedValue(k).ValueType()!=JsonValueType::String)throw std::invalid_argument("Missing tile ID");auto s=winrt::to_string(o.GetNamedString(k));if(s.empty())throw std::invalid_argument("Empty tile ID");return s;}
inline bool flag(const JsonObject& o,const wchar_t* k){if(!o.HasKey(k))return false;if(o.GetNamedValue(k).ValueType()!=JsonValueType::Boolean)throw std::invalid_argument("Invalid tile flag");return o.GetNamedBoolean(k);}
inline void number(JsonObject o,const wchar_t* k,double n){o.Insert(k,JsonValue::CreateNumberValue(n));}
inline void text(JsonObject o,const wchar_t* k,const std::string& s){o.Insert(k,JsonValue::CreateStringValue(winrt::to_hstring(s)));}
inline JsonObject encode(const tiles::CelData& d){JsonObject o;number(o,L"tileWidth",d.tileWidth);number(o,L"tileHeight",d.tileHeight);number(o,L"columns",d.columns);number(o,L"rows",d.rows);JsonArray cells;for(std::size_t i=0;i<d.cells.size();++i)if(d.cells[i]){auto c=*d.cells[i];JsonObject v;number(v,L"index",double(i));text(v,L"tilesetId",c.tilesetId);text(v,L"tileId",c.tileId);if(c.flipHorizontal)v.Insert(L"flipHorizontal",JsonValue::CreateBooleanValue(true));if(c.flipVertical)v.Insert(L"flipVertical",JsonValue::CreateBooleanValue(true));if(c.rotation)number(v,L"rotation",c.rotation);cells.Append(v);}o.Insert(L"cells",cells);return o;}
inline tiles::CelData decode(const JsonObject& o){tiles::CelData d;d.tileWidth=integer(o,L"tileWidth",1,256);d.tileHeight=integer(o,L"tileHeight",1,256);d.columns=integer(o,L"columns",1,int(tiles::MaxCells));d.rows=integer(o,L"rows",1,int(tiles::MaxCells));tiles::sizeCheck(d.tileWidth,d.tileHeight,d.columns,d.rows);d.cells.assign(std::size_t(d.columns)*d.rows,{});std::set<std::size_t> seen;for(auto v:o.GetNamedArray(L"cells")){auto c=v.GetObject();auto i=std::size_t(integer(c,L"index",0,int(d.cells.size()-1)));if(!seen.insert(i).second)throw std::invalid_argument("Duplicate tile cell");tiles::Cell cell{string(c,L"tilesetId"),string(c,L"tileId"),flag(c,L"flipHorizontal"),flag(c,L"flipVertical"),0};if(c.HasKey(L"rotation"))cell.rotation=integer(c,L"rotation",0,3);d.cells[i]=std::move(cell);}return d;}
inline void validate(const tiles::Tileset& t){tiles::sizeCheck(t.tileWidth,t.tileHeight,t.columns,t.rows,true);if(t.id.empty()||t.tileIds.empty()||t.tileIds.size()>std::size_t(t.columns)*t.rows||t.pixels.size()!=std::size_t(t.columns)*t.rows*t.tileWidth*t.tileHeight||t.tileSlots.size()>tiles::MaxLayoutSlots)throw std::invalid_argument("Invalid tileset metadata");std::set<std::string> ids,slots;for(auto& id:t.tileIds)if(id.empty()||!ids.insert(id).second)throw std::invalid_argument("Invalid tile ID");for(auto& id:t.tileSlots)if(id&&(!ids.count(*id)||!slots.insert(*id).second))throw std::invalid_argument("Invalid tile slot");}
inline void validateAndRender(timeline::State& state){std::set<std::string> setIds;for(auto& s:state.tilesets){validate(s);if(!setIds.insert(s.id).second)throw std::invalid_argument("Duplicate tileset ID");}for(auto& l:state.layers){auto owner=std::find_if(state.tilesets.begin(),state.tilesets.end(),[&](const auto& t){return t.id==l.tilemapTilesetId;});if(l.kind=="tilemap"&&owner==state.tilesets.end())throw std::invalid_argument("Missing layer tileset");for(auto& c:state.cels)if(c.layerId==l.id){if(l.kind!="tilemap"){if(c.tilemap)throw std::invalid_argument("Tilemap metadata on raster layer");continue;}if(!c.linkedCelId&& !c.tilemap)throw std::invalid_argument("Missing tilemap cells");if(!c.tilemap)continue;auto& grid=*c.tilemap;if(grid.tileWidth!=owner->tileWidth||grid.tileHeight!=owner->tileHeight)throw std::invalid_argument("Tilemap dimensions differ");for(auto& v:grid.cells)if(v){auto t=std::find_if(state.tilesets.begin(),state.tilesets.end(),[&](const auto& s){return s.id==v->tilesetId;});if(t==state.tilesets.end()||t->tileWidth!=grid.tileWidth||t->tileHeight!=grid.tileHeight||!tiles::Index(*t).find(v->tileId))throw std::invalid_argument("Missing tile reference");}timeline::Surface s;if(c.surface){s.offsetX=c.surface->offsetX;s.offsetY=c.surface->offsetY;}s.width=grid.columns*grid.tileWidth;s.height=grid.rows*grid.tileHeight;s.pixels=tiles::render(grid,state.tilesets);c.surface=std::move(s);}}}
}
